import{_ as a,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Personalización","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/customize.md","filePath":"es/guide/customize.md","lastUpdated":1793163976000}'),n={name:"es/guide/customize.md"};function t(s,e,l,d,c,p){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="personalizacion" tabindex="-1">Personalización <a class="header-anchor" href="#personalizacion" aria-label="Permalink to &quot;Personalización&quot;">​</a></h1><p>Haz que NueZip sea verdaderamente tuyo personalizando tu experiencia de gestión de archivos. Esta guía cubre todo lo que puedes personalizar.</p><h2 id="preferencias-generales" tabindex="-1">Preferencias generales <a class="header-anchor" href="#preferencias-generales" aria-label="Permalink to &quot;Preferencias generales&quot;">​</a></h2><p>Abre <strong>NueZip → Ajustes</strong> (o pulsa <code>Cmd+,</code>) para acceder a todas las opciones de personalización.</p><h3 id="apariencia" tabindex="-1">Apariencia <a class="header-anchor" href="#apariencia" aria-label="Permalink to &quot;Apariencia&quot;">​</a></h3><ul><li><strong>Tema</strong>: Elige entre Claro, Oscuro o Sistema (sigue la apariencia de macOS)</li><li><strong>Estilo de icono</strong>: Define un icono de barra de menú monocromo o a todo color</li><li><strong>Idioma</strong>: Selecciona entre los idiomas compatibles (English, 中文, 日本語, 한국어, y más)</li></ul><h2 id="valores-predeterminados-de-compresion" tabindex="-1">Valores predeterminados de compresión <a class="header-anchor" href="#valores-predeterminados-de-compresion" aria-label="Permalink to &quot;Valores predeterminados de compresión&quot;">​</a></h2><p>Define tus valores predeterminados de compresión preferidos:</p><table tabindex="0"><thead><tr><th>Ajuste</th><th>Opciones</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Formato predeterminado</strong></td><td>ZIP, 7z, TAR, GZIP, BZIP2, XZ</td><td>Formato de archivo para compresión rápida</td></tr><tr><td><strong>Nivel de compresión</strong></td><td>Store, Fast, Normal, Maximum, Ultra</td><td>Compensación entre velocidad y relación</td></tr><tr><td><strong>Cifrado</strong></td><td>None, AES-128, AES-256</td><td>Cifrado predeterminado para archivos ZIP/7z</td></tr><tr><td><strong>Tamaño de volumen</strong></td><td>Personalizado (MB)</td><td>Tamaño de división predeterminado para archivos multi-volumen</td></tr></tbody></table><h3 id="configuracion-de-ejemplo" tabindex="-1">Configuración de ejemplo <a class="header-anchor" href="#configuracion-de-ejemplo" aria-label="Permalink to &quot;Configuración de ejemplo&quot;">​</a></h3><p>Para uso diario:</p><ul><li><strong>Formato</strong>: ZIP</li><li><strong>Nivel</strong>: Normal</li><li><strong>Cifrado</strong>: AES-256 (para archivos sensibles)</li><li><strong>Volumen</strong>: Desactivado</li></ul><p>Para archivar:</p><ul><li><strong>Formato</strong>: 7-Zip</li><li><strong>Nivel</strong>: Ultra</li><li><strong>Cifrado</strong>: AES-256</li><li><strong>Volumen</strong>: 4,7 GB (para caber en DVD)</li></ul><h2 id="preferencias-de-extraccion" tabindex="-1">Preferencias de extracción <a class="header-anchor" href="#preferencias-de-extraccion" aria-label="Permalink to &quot;Preferencias de extracción&quot;">​</a></h2><p>Personaliza el comportamiento de extracción:</p><ul><li><strong>Extraer a subcarpeta por defecto</strong>: Crea automáticamente una carpeta con nombre al extraer</li><li><strong>Abrir carpeta tras la extracción</strong>: Muestra los contenidos extraídos en Finder</li><li><strong>Comportamiento de sobrescritura</strong>: Preguntar, Sobrescribir siempre o Omitir archivos existentes</li><li><strong>Conservar fechas de archivos</strong>: Mantiene las marcas de tiempo originales del archivo</li></ul><h2 id="extension-de-finder" tabindex="-1">Extensión de Finder <a class="header-anchor" href="#extension-de-finder" aria-label="Permalink to &quot;Extensión de Finder&quot;">​</a></h2><p>Gestiona la integración del menú contextual de Finder:</p><ul><li><strong>Habilitar/Deshabilitar</strong>: Activa o desactiva los elementos del menú con clic derecho</li><li><strong>Acciones rápidas</strong>: Elige qué acciones aparecen en el menú contextual <ul><li>Extraer aquí</li><li>Extraer a carpeta</li><li>Comprimir a ZIP</li><li>Comprimir con opciones</li></ul></li></ul><p>Gestiona esto en: <strong>Configuración del sistema → Privacidad y seguridad → Extensiones → Extensiones de Finder</strong></p><h2 id="icono-de-la-barra-de-menu-bandeja" tabindex="-1">Icono de la barra de menú (bandeja) <a class="header-anchor" href="#icono-de-la-barra-de-menu-bandeja" aria-label="Permalink to &quot;Icono de la barra de menú (bandeja)&quot;">​</a></h2><p>Personaliza el panel de la barra de menú:</p><ul><li><strong>Mostrar en la barra de menú</strong>: Activa/desactiva el icono de la bandeja</li><li><strong>Cerrar panel automáticamente</strong>: Cierra el panel de desecho tras la extracción</li><li><strong>Archivos recientes</strong>: Número de elementos recientes a mostrar</li><li><strong>Salir al cerrar</strong>: Si la app permanece en segundo plano</li></ul><h2 id="notificaciones" tabindex="-1">Notificaciones <a class="header-anchor" href="#notificaciones" aria-label="Permalink to &quot;Notificaciones&quot;">​</a></h2><ul><li><strong>Mostrar avisos de finalización</strong>: Avisa cuando terminan las operaciones largas</li><li><strong>Mostrar avisos de error</strong>: Muestra notificaciones para operaciones fallidas</li><li><strong>Sonido</strong>: Reproduce un sonido al completar las operaciones</li></ul><h2 id="ajustes-generales" tabindex="-1">Ajustes generales <a class="header-anchor" href="#ajustes-generales" aria-label="Permalink to &quot;Ajustes generales&quot;">​</a></h2><p>Accede a estos en <strong>Ajustes → General</strong>:</p><ul><li><strong>Idioma</strong>: Cambia entre English, 中文, 日本語, y más</li><li><strong>Iniciar al iniciar sesión</strong>: NueZip se inicia automáticamente al iniciar sesión</li><li><strong>Tema</strong>: Modo claro u oscuro (sigue al sistema por defecto)</li><li><strong>Icono de barra de menú</strong>: Muestra u oculta el icono de la barra de menú</li></ul><h2 id="consejos" tabindex="-1">Consejos <a class="header-anchor" href="#consejos" aria-label="Permalink to &quot;Consejos&quot;">​</a></h2><ul><li>Define tus valores predeterminados de compresión favoritos una vez para agilizar el archivado diario</li><li>Habilita &quot;Iniciar al iniciar sesión&quot; para que NueZip esté siempre a un clic de distancia</li><li>Usa la extensión de Finder para el flujo de trabajo de extracción/compresión más rápido</li><li>Revisa el acceso a carpetas periódicamente en Configuración del sistema para mantener todo ordenado</li></ul>',31)])])}const g=a(n,[["render",t]]);export{m as __pageData,g as default};
